#!/usr/bin/env bun
/**
 * sync-docs.ts — DRY docs pipeline for docs.phux.sh
 * ----------------------------------------------------------------------------
 * Reads selected markdown from the phux source repo and writes it into
 * `src/content/docs/_synced/` as the source for an Astro content collection.
 *
 * We do NOT hand-copy docs. Everything under `_synced/` is gitignored and
 * regenerated by this producer. If a synced page renders wrong, fix the
 * responsible adjacent docs-catalog/markdown/output module — never edit a
 * file under `_synced/`.
 *
 * phux's docs are a flat `docs/*.md` (hand-written pages) plus the generated
 * `docs/reference/*.md`. The hand-written pages are listed in ORIENTATION with
 * their slug and nav group; the reference directory is globbed, so a new
 * generated page flows through with no edit here.
 *
 * What it does, per file:
 *   1. Writes the site's collection schema frontmatter (title, summary, group,
 *      order, sourcePath, stability). The source pages carry no frontmatter.
 *   1b. A directory README with children is written as `<prefix>/index.md`,
 *      and each folder gets a Fumadocs `meta.json` (title + explicit `pages`
 *      order). The URL slug stays the bare prefix either way.
 *   2. Derives `title` from the first `# H1` and `summary` from the first
 *      paragraph after it.
 *   3. Rewrites relative `*.md` links between docs into site routes
 *      (e.g. `./agents.md` -> `/agents`, `./reference/cli.md` -> `/reference/cli`).
 *   4. Rewrites links to files that DON'T live on this site (crates/,
 *      CONTRIBUTING.md, README.md) into absolute GitHub URLs so they still work.
 *
 * Idempotent: the `_synced/` dir is wiped and rebuilt on every run, so a clean
 * `bun run sync-docs` always produces the same tree from the same source.
 *
 * Env:
 *   PHUX_ROOT      — phux checkout. Default: ../../phux or ../phux.
 *   PHUX_DOCS_DIR  — phux `docs/` dir. Default: `$PHUX_ROOT/docs`.
 *
 * CI checks out no-phux/phux and sets PHUX_ROOT. A push to phux that changes
 * docs, installers, or product skills dispatches this repo; the weekly cron
 * is the backstop.
 * ---------------------------------------------------------------------------
 */

import { execFileSync } from "node:child_process";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { discover } from "./docs-catalog";
import { writeDocumentation } from "./docs-output";
import { phuxRoot } from "./phux-root";

const ROOT = resolve(import.meta.dir, "..");
const PHUX_ROOT = phuxRoot(ROOT);
const DOCS_DIR = process.env.PHUX_DOCS_DIR ? resolve(process.env.PHUX_DOCS_DIR) : join(PHUX_ROOT, "docs");
const OUT_DIR = join(ROOT, "src/content/docs/_synced");
const MANIFEST_PATH = join(ROOT, "public/docs-manifest.json");

// The curl installers are published from this same repo, the same way the docs
// are: each `scripts/install*.sh` is the only copy, and the site serves its
// bytes verbatim. Both filenames get the identical script rather than one
// redirecting to the other, so `curl https://phux.sh/install` needs no -L to
// follow.
const INSTALLERS: { src: string; dests: readonly [string, string] }[] = [
  {
    src: join(PHUX_ROOT, "scripts/install.sh"),
    dests: ["public/install", "public/install.sh"],
  },
  {
    src: join(PHUX_ROOT, "scripts/install-desktop.sh"),
    dests: ["public/install-desktop", "public/install-desktop.sh"],
  },
];

function sourceRevision(): string {
  const revision =
    process.env.PHUX_SOURCE_REVISION ??
    execFileSync("git", ["-C", PHUX_ROOT, "rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  if (!/^[0-9a-f]{40}$/i.test(revision)) throw new Error(`invalid phux source revision: ${revision}`);
  return revision;
}

function siteRevision(): string {
  const revision = execFileSync("git", ["-C", ROOT, "rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  if (!/^[0-9a-f]{40}$/i.test(revision)) throw new Error(`invalid site revision: ${revision}`);
  return revision;
}

const SOURCE_REVISION = sourceRevision();

/**
 * Publish the CLI and GPUI desktop installers (also with .sh suffix).
 *
 * Nothing here is committed — every destination is gitignored and rewritten on
 * every build — so the bytes a stranger pipes to `sh` cannot drift from the
 * scripts `scripts/test-install.sh` exercises. The shebang assertion is the
 * cheap half of that contract: a served script is consumed by `sh`, and a
 * bash shebang means somebody reintroduced bashisms that dash will reject on a
 * user's machine rather than in CI.
 */
async function syncInstaller(): Promise<void> {
  // A rebuild of an existing checkout must not republish retired generated assets.
  await rm(join(ROOT, "public/install-cockpit"), { force: true });
  await rm(join(ROOT, "public/install-cockpit.sh"), { force: true });
  for (const { src, dests } of INSTALLERS) {
    const script = await readFile(src, "utf8");
    if (!script.startsWith("#!/bin/sh\n")) {
      throw new Error(
        `${src} must start with #!/bin/sh: it is served at https://phux.sh and piped straight to sh`,
      );
    }
    for (const dest of dests) {
      await writeFile(join(ROOT, dest), script, { mode: 0o755 });
    }
  }
  console.log("sync-docs: published /install and /install-desktop (+.sh)");
}

async function readVersionMetadata() {
  const [protocolSource, cargoSource] = await Promise.all([
    readFile(join(PHUX_ROOT, "crates/phux-protocol/src/lib.rs"), "utf8"),
    readFile(join(PHUX_ROOT, "Cargo.toml"), "utf8"),
  ]);
  const version = protocolSource.match(
    /PROTOCOL_VERSION:\s*Version\s*=\s*Version\s*{[\s\S]*?major:\s*(\d+)[\s\S]*?minor:\s*(\d+)[\s\S]*?patch:\s*(\d+)/,
  );
  const projectVersion = cargoSource.match(/\[workspace\.package\][\s\S]*?\nversion\s*=\s*"([^"]+)"/)?.[1];
  if (!version || !projectVersion) throw new Error("could not derive phux protocol/project version");
  return {
    protocolVersion: `${version[1]}.${version[2]}.${version[3]}`,
    projectVersion,
  };
}

function reportExcluded(excluded: string[]): void {
  if (!excluded.length) return;
  console.log(`sync-docs: excluded ${excluded.length} internal doc(s):`);
  for (const path of excluded.sort()) console.log(`  - ${path}`);
}

function reportResult(written: number, failed: string[]): void {
  console.log(`sync-docs: wrote ${written} page(s), from ${DOCS_DIR}`);
  if (failed.length) {
    console.error(`sync-docs: ${failed.length} file(s) failed to resolve:`);
    for (const path of failed) console.error(`  - ${path}`);
    process.exitCode = 1;
  }
  if (written === 0) {
    console.error("sync-docs: nothing written — is PHUX_DOCS_DIR correct?");
    process.exit(1);
  }
}

async function run() {
  // Fully regenerate for reproducibility / idempotency.
  await rm(OUT_DIR, { recursive: true, force: true });
  await mkdir(OUT_DIR, { recursive: true });
  const versions = await readVersionMetadata();
  const { entries, excluded } = await discover(DOCS_DIR);
  const { written, failed } = await writeDocumentation(OUT_DIR, entries, SOURCE_REVISION, versions, siteRevision());
  await syncInstaller();
  await writeFile(
    MANIFEST_PATH,
    `${JSON.stringify(
      {
        repository: "no-phux/phux",
        revision: SOURCE_REVISION,
        protocolVersion: versions.protocolVersion,
        projectVersion: versions.projectVersion,
      },
      null,
      2,
    )}\n`,
  );
  reportExcluded(excluded);
  reportResult(written, failed);
}

run().catch((err) => {
  console.error("sync-docs failed:", err);
  process.exit(1);
});
